def removeDuplicates(nums: list[int]) -> int:
    stack_size = 2
    for i in range(2, len(nums)):
        # 与有效前缀倒数第二个值比较，防止写入第三次。
        if nums[i] != nums[stack_size - 2]:
            nums[stack_size] = nums[i]
            stack_size += 1
    return min(stack_size, len(nums))

